window.DEX_DATA["sources:backport-4d36607cc8a13bfd"]={"json":{"skins":[{"filename":"schoolgirl.png"}],"names":[{"name":"麦迪逊"},{"name":"凯莉"},{"name":"奥德丽"},{"name":"格蕾丝"},{"name":"莉莉"}],"chat":[{"lines":[{"text":"学校里能学到很多有趣的东西，可我还是想快点当训练家。"},{"text":"能参加巡护员组织的夏日活动，也很不错！"}]},{"lines":[{"text":"我得赶快回家，不然要错过小火马动画啦！"},{"text":"等我看重播之前，朋友们就会把剧情全说出来……"}]},{"lines":[{"text":"有两千宝可元，每个精灵球两百，我能拿到几个球？"},{"text":"十一个！这是脑筋急转弯，还能得到赠送的纪念球！"}]},{"lines":[{"text":"今天，老师没收了科迪的精灵球。"},{"text":"他一直拿着玩，打扰大家。"}]}]}};
